# ============================================================================
#  AutoUpload one-file installer (Windows 10/11)
#
#  Turns a long YouTube video (or podcast) into edited vertical Shorts and
#  uploads them to YouTube automatically:
#    /autoupload <youtube-url>  ->  5 published Shorts (cut, captioned, zoomed,
#                                   whooshed, scheduled 2/day by default)
#
#  This file bundles the skill code ONLY. It contains NO credentials, NO API
#  keys, NO tokens. During install you create your OWN free Google Cloud
#  credentials - the PLACEHOLDER values shown are examples only; put your real
#  ones only in your local files, never back into this script.
#
#  Run it (from PowerShell):
#    powershell -NoProfile -ExecutionPolicy Bypass -File installer-for-windows.ps1
#  or double-click run-installer-windows.cmd next to this file.
#
#  What it does: installs deps via winget (Python 3.12, ffmpeg, yt-dlp),
#  unpacks the skills into ~\.claude\skills, sets up Python venvs, walks you
#  through the one-time Google/YouTube authorization, and runs health checks.
# ============================================================================

$SkillsDir = $env:AUTOUPLOAD_INSTALL_DIR
if (-not $SkillsDir) { $SkillsDir = "$env:USERPROFILE\.claude\skills" }
$ClipperDir = Join-Path $SkillsDir "clipper"
$AutoupDir  = Join-Path $SkillsDir "autoupload"

function Say($t)  { Write-Host ""; Write-Host "== $t ==" -ForegroundColor Cyan }
function Step($t) { Write-Host "  $t" }

# ---- embedded payload: base64 of a .tar holding clipper/ and autoupload/ ----
$payload = @'

'@

$tarPath = Join-Path $env:TEMP "autoupload-skills.tar"
[IO.File]::WriteAllBytes($tarPath, [Convert]::FromBase64String($payload.Trim()))

if ($env:AUTOUPLOAD_PAYLOAD_ONLY -eq "1") {
    New-Item -ItemType Directory -Force -Path $SkillsDir | Out-Null
    tar -xf $tarPath -C $SkillsDir
    Write-Host "payload extracted to $SkillsDir"
    exit 0
}

Say "1/5 Installing system dependencies (winget)"

if ($null -eq (Get-Command tar -ErrorAction SilentlyContinue)) {
    Write-Host "ERROR: tar.exe not found. It ships with Windows 10 (1803+) and Windows 11."
    exit 1
}

$haveWinget = $null -ne (Get-Command winget -ErrorAction SilentlyContinue)
if (-not $haveWinget) {
    Step "winget not found - install these manually, then rerun this script:"
    Step "  Python 3.12   https://www.python.org/downloads/"
    Step "  ffmpeg        https://www.gyan.dev/ffmpeg/builds/"
    Step "  yt-dlp        https://github.com/yt-dlp/yt-dlp/releases"
} else {
    Step "winget found - this can take a few minutes..."
    foreach ($p in @(@("Python.Python.3.12", "python 3.12"),
                     @("Gyan.FFmpeg", "ffmpeg"),
                     @("yt-dlp.yt-dlp", "yt-dlp"))) {
        Step "installing $($p[1]) ..."
        & winget install --silent --accept-source-agreements --accept-package-agreements -e --id $p[0] | Out-Null
        if ($LASTEXITCODE -ne 0) {
            Step "  note: winget returned $LASTEXITCODE for $($p[1]) (often just 'already installed')"
        }
    }
    # make freshly installed tools visible in THIS session too
    $env:Path = [Environment]::GetEnvironmentVariable("Path", "Machine") + ";" +
                [Environment]::GetEnvironmentVariable("Path", "User") + ";" + $env:Path
}

# ---- python helpers ----
function Find-Python {
    $tries = @(@("py", "-3.12"), @("py", "-3"), @("python", $null))
    foreach ($t in $tries) {
        if ($null -eq (Get-Command $t[0] -ErrorAction SilentlyContinue)) { continue }
        $check = @()
        if ($t[1]) { $check += $t[1] }
        $check += @("-c", "import sys; sys.exit(0 if (3,10) <= sys.version_info[:2] else 1)")
        & $t[0] @check 2>$null | Out-Null
        if ($LASTEXITCODE -eq 0) { return $t }
    }
    return $null
}

function Make-Venv($dir, $pkgs) {
    $py = Find-Python
    if ($null -eq $py) {
        Write-Host "ERROR: Python 3.10+ not found. Install it from https://www.python.org/downloads/ then rerun."
        exit 1
    }
    $vpy = Join-Path $dir ".venv\Scripts\python.exe"
    if (-not (Test-Path $vpy)) {
        if ($py[1]) { & $py[0] $py[1] -m venv $dir } else { & $py[0] -m venv $dir }
        if (-not (Test-Path $vpy)) { Write-Host "ERROR: could not create venv at $dir"; exit 1 }
    }
    & $vpy -m pip install --quiet --upgrade pip
    & $vpy -m pip install --quiet certifi @pkgs
    if ($LASTEXITCODE -ne 0) { Write-Host "ERROR: pip install failed for $dir"; exit 1 }
    # SSL cert fix (harmless on Windows, helps on odd CA setups)
    $site = (& $vpy -c "import site; print(site.getsitepackages()[0])").Trim()
    $sc = @'
import os
try:
    import certifi
    _b = certifi.where()
    os.environ.setdefault("SSL_CERT_FILE", _b)
    os.environ.setdefault("REQUESTS_CA_BUNDLE", _b)
except Exception:
    pass
'@
    Set-Content -Path (Join-Path $site "sitecustomize.py") -Value $sc -Encoding ASCII
}

Say "2/5 Unpacking skills to $SkillsDir"
New-Item -ItemType Directory -Force -Path $SkillsDir | Out-Null
tar -xf $tarPath -C $SkillsDir
Step "clipper     (fetch / transcribe / cut / caption / edit / check)"
Step "autoupload  (YouTube upload + scheduling)"

Say "3/5 Setting up Python environments (one time, a few minutes)"
Step "clipper venv (speech model, video tools) - this is the big one..."
Make-Venv $ClipperDir @("faster-whisper", "opencv-python<5", "numpy", "Pillow", "yt-dlp")
Step "autoupload venv (YouTube API)..."
Make-Venv $AutoupDir @("google-api-python-client", "google-auth-oauthlib", "google-auth-httplib2")

Say "4/5 Your own YouTube credentials (NO keys are bundled in this file)"
$secretPath = Join-Path $AutoupDir "client_secret.json"
$tokenPath  = Join-Path $AutoupDir "token.json"

$ans = Read-Host "Create your Google credentials now? [Y/n]"
if ($ans -eq "" -or $ans -eq "Y" -or $ans -eq "y") {
    Write-Host ""
    Write-Host "  One-time setup (~5 minutes, free):"
    Write-Host "  1. Go to https://console.cloud.google.com/"
    Write-Host "     -> create a project named e.g.  YOUR_PROJECT_NAME"
    Write-Host "  2. APIs & Services -> Library -> search 'YouTube Data API v3' -> Enable"
    Write-Host "  3. APIs & Services -> OAuth consent screen -> External"
    Write-Host "     -> app name = YOUR_APP_NAME , email = YOUR_EMAIL@example.com"
    Write-Host "     -> add YOUR_EMAIL@example.com as a test user"
    Write-Host "  4. APIs & Services -> Credentials -> Create credentials"
    Write-Host "     -> OAuth client ID -> Desktop app -> Download JSON"
    Write-Host "  5. Save that file as:  $secretPath"
    Write-Host ""
    while ($true) {
        $a2 = Read-Host "Press Enter when client_secret.json is saved (or type s to skip)"
        if ($a2 -eq "s") { break }
        if (Test-Path $secretPath) { break }
        Write-Host "  not found yet at $secretPath"
    }
}

if (Test-Path $secretPath) {
    Step "starting the one-time browser login (a browser window will open)..."
    $authPy = Join-Path $AutoupDir ".venv\Scripts\python.exe"
    & $authPy (Join-Path $AutoupDir "scripts\auth_setup.py")
    if ($LASTEXITCODE -ne 0) {
        Write-Host "  login did not finish - run it later:"
        Write-Host "    & '$authPy' '$(Join-Path $AutoupDir 'scripts\auth_setup.py')'"
    }
} else {
    Write-Host "  skipped for now. When ready, save your OAuth client JSON as:"
    Write-Host "    $secretPath    (PLACEHOLDER - your own file)"
    Write-Host "  then run:"
    Write-Host "    & '$(Join-Path $AutoupDir '.venv\Scripts\python.exe')' '$(Join-Path $AutoupDir 'scripts\auth_setup.py')'"
}

Say "5/5 Health checks"
$script:pass = $true
function Check($name, $ok, $hint) {
    if ($ok) { Write-Host ("  {0,-16} ok" -f $name) -ForegroundColor Green }
    else {
        Write-Host ("  {0,-16} FAIL - {1}" -f $name, $hint) -ForegroundColor Yellow
        $script:pass = $false
    }
}

$ff = Get-Command ffmpeg -ErrorAction SilentlyContinue
Check "ffmpeg" ($null -ne $ff) "winget install Gyan.FFmpeg, then open a NEW terminal"
$yd = Get-Command yt-dlp -ErrorAction SilentlyContinue
Check "yt-dlp" ($null -ne $yd) "winget install yt-dlp.yt-dlp, then open a NEW terminal"

$clipPy = Join-Path $ClipperDir ".venv\Scripts\python.exe"
$clipOk = $false
if (Test-Path $clipPy) {
    & $clipPy -c "import faster_whisper, cv2, numpy, PIL, yt_dlp" 2>$null
    $clipOk = ($LASTEXITCODE -eq 0)
}
Check "clipper-venv" $clipOk "rerun this installer"

$autoPy = Join-Path $AutoupDir ".venv\Scripts\python.exe"
$autoOk = $false
if (Test-Path $autoPy) {
    & $autoPy -c "import googleapiclient, google.oauth2, google_auth_oauthlib" 2>$null
    $autoOk = ($LASTEXITCODE -eq 0)
}
Check "autoupload-venv" $autoOk "rerun this installer"
Check "client_secret" (Test-Path $secretPath) "see step 4/5 above"
Check "token" (Test-Path $tokenPath) "browser login (step 4/5)"

Write-Host ""
Write-Host "==============================================================="
if (-not $script:pass) {
    Write-Host "  Some checks FAILED above. Fix the FAIL lines (usually:" -ForegroundColor Yellow
    Write-Host "  open a NEW terminal so PATH refreshes, or rerun the" -ForegroundColor Yellow
    Write-Host "  installer), then rerun. Everything else is already done." -ForegroundColor Yellow
    Write-Host "==============================================================="
}

Write-Host ""
Write-Host "  How to use (in Claude Code - restart Claude if it was open):"
Write-Host "      /autoupload <youtube-url>"
Write-Host "  or just:  'clip this video and upload it as Shorts'"
Write-Host ""
Write-Host "  - clips land in  ~\Desktop\Clipper\<name>-<video-id>\clips"
Write-Host "  - first transcription downloads a ~500 MB speech model, once"
Write-Host "  - Short titles/captions are editable in  clips\clip-NN.txt"
Write-Host "  - uploads schedule 2/day by default (15:00 & 22:00 slots)"
Write-Host "  - YouTube quota: 1600 units per upload, 10000/day on a free"
Write-Host "    project - so one 5-clip run per day; rerun the next day"
Write-Host "  - the Google login needs a browser on this machine"
Write-Host ""
Write-Host "  Privacy: this installer contained no keys. Your credentials"
Write-Host "  live only in  autoupload\client_secret.json  and  token.json"
Write-Host "  - never share those two files."
Write-Host "==============================================================="

